// Build the send queue: the first N leads in the sheet that have not been emailed yet.
// "Chronological" = sheet order, top to bottom. Rows arrive from the Sheets node in that order.

const LIMIT = 300;            // <- how many emails this run sends
const STATUS_COL = 'Status';  // <- column that marks a lead as handled
const EMAIL_COL  = 'Email';

const seen = new Set();
const queue = [];

for (const item of $input.all()) {
  const row = item.json;

  const email  = String(row[EMAIL_COL] ?? '').trim().toLowerCase();
  const status = String(row[STATUS_COL] ?? '').trim();

  if (!email || !email.includes('@')) continue;  // no usable address
  if (status) continue;                          // already emailed / skipped / bounced
  if (seen.has(email)) continue;                 // same address twice in the list

  seen.add(email);
  queue.push({ json: { ...row, _to: email } });

  if (queue.length >= LIMIT) break;
}

if (queue.length === 0) {
  throw new Error('Nothing to send: every row either has no email or already has a Status.');
}

return queue;

// Runs once, after the last lead. Gives you a one-line result in the UI.
const attempted = $('Build send queue').all().length;
return [{ json: { attempted, finishedAt: $now.toISO(),
  note: 'Check the Status column in the sheet for per-lead Emailed / Failed.' } }];

// Turn one sheet row into a subject + plain text body.
const INFO_URL = 'https://www.fcurban.com/groups-and-company-pitch-rental/football-pitch-rental-for-groups-corporates';

const row      = $json;
const business = String(row['Business'] ?? '').trim() || 'there';
const venue    = String(row['Nearest FC Urban venue'] ?? '').trim();
const city     = String(row['City'] ?? '').trim() || 'your city';
const walk     = Number(row['Walk (min)']);
const type     = String(row['Email type'] ?? '').trim();

// "Hi Ben," when the address clearly belongs to a person, otherwise "Hi <Company> team,".
let greeting = `Hi ${business} team,`;
if (type === 'person_or_other') {
  const local = String(row['_to']).split('@')[0].replace(/[._\-+0-9].*$/, '');
  const generic = ['info', 'hello', 'hi', 'contact', 'office', 'enquiries', 'enquiry',
                   'admin', 'sales', 'press', 'events', 'team', 'mail', 'support'];
  if (/^[a-z]{2,15}$/i.test(local) && !generic.includes(local.toLowerCase())) {
    greeting = `Hi ${local.charAt(0).toUpperCase() + local.slice(1)},`;
  }
}

// Proximity line, only claimed when we actually have a venue in the sheet.
let proximity;
if (venue && Number.isFinite(walk) && walk > 0) {
  proximity = `We already organise games at ${venue}, around a ${walk} minute walk from your ${city} office.`;
} else if (venue) {
  proximity = `We already organise games at ${venue}, just around the corner from your ${city} office.`;
} else {
  proximity = `We already organise games across ${city}.`;
}

const subject = `After work football for the ${business} team`;

const body = [
  greeting,
  ``,
  `I'm Joe from FC Urban. We organise social football games across ${city} where people can simply turn up and play.`,
  ``,
  proximity,
  ``,
  `We are looking for local companies who might be interested in playing regular football together after work.`,
  ``,
  `FC Urban takes care of the pitch, payments and organisation. For smaller teams, we can also fill the remaining spaces with other FC Urban players, so it can be an easy weekly social without someone internally having to organise everything.`,
  ``,
  `Would this be something the ${business} team might be interested in trying?`,
  ``,
  `You can find more information here:`,
  INFO_URL,
  ``,
  `Best,`,
  ``,
  `Joe`,
  `FC Urban`,
  ``,
  `--`,
  `You are receiving this at a business address because we think FC Urban could be a fit for your team. Reply with "no thanks" and I won't contact you again.`,
].join('\n');

return { json: { ...row, to: row._to, subject, body } };

